source='''from collections import deque

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=max(set(v for row in g for v in row), key=lambda c:sum(row.count(c) for row in g))
    seen=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and (r,c) not in seen:
                g[r][c]=2
    # Enclosed regions with odd side length are filled with 7; even ones with 2.
    unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]==bg and (r,c) not in seen}
    while unseen:
        start=unseen.pop(); comp={start}; stack=[start]
        while stack:
            r,c=stack.pop()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in unseen:
                    unseen.remove((nr,nc)); comp.add((nr,nc)); stack.append((nr,nc))
        color=2 if len(comp)%2==0 else 7
        for r,c in comp: g[r][c]=color
    return g
'''
